"""Build the assignment PDF from the plots and metrics generated by pid_control.py."""

from __future__ import annotations

import csv
import math
from pathlib import Path

from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import inch
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import (
    Image,
    PageBreak,
    Paragraph,
    SimpleDocTemplate,
    Spacer,
    Table,
    TableStyle,
)


ROOT = Path(__file__).resolve().parent
FIGURES = ROOT / "figures"
METRICS_PATH = ROOT / "metrics.csv"
OUTPUT = ROOT / "PID_Control_Assignment.pdf"

FONT_DIR = Path("C:/Windows/Fonts")
TIMES_REGULAR = "TimesNewRoman"
TIMES_BOLD = "TimesNewRoman-Bold"
TIMES_ITALIC = "TimesNewRoman-Italic"
TIMES_BOLD_ITALIC = "TimesNewRoman-BoldItalic"


def register_fonts() -> tuple[str, str, str, str]:
    font_files = {
        TIMES_REGULAR: FONT_DIR / "times.ttf",
        TIMES_BOLD: FONT_DIR / "timesbd.ttf",
        TIMES_ITALIC: FONT_DIR / "timesi.ttf",
        TIMES_BOLD_ITALIC: FONT_DIR / "timesbi.ttf",
    }
    if all(path.exists() for path in font_files.values()):
        for name, path in font_files.items():
            pdfmetrics.registerFont(TTFont(name, str(path)))
        pdfmetrics.registerFontFamily(
            TIMES_REGULAR,
            normal=TIMES_REGULAR,
            bold=TIMES_BOLD,
            italic=TIMES_ITALIC,
            boldItalic=TIMES_BOLD_ITALIC,
        )
        return TIMES_REGULAR, TIMES_BOLD, TIMES_ITALIC, TIMES_BOLD_ITALIC
    return "Times-Roman", "Times-Bold", "Times-Italic", "Times-BoldItalic"


def styles(font, bold_font, italic_font, bold_italic_font):
    base = getSampleStyleSheet()
    base.add(ParagraphStyle(
        name="CoverTitle", parent=base["Title"], fontName=bold_font,
        fontSize=22, leading=26, alignment=TA_CENTER, textColor=colors.black,
        spaceAfter=5,
    ))
    base.add(ParagraphStyle(
        name="CoverSub", parent=base["Normal"], fontName=font, fontSize=11,
        leading=14, alignment=TA_CENTER, textColor=colors.black, spaceAfter=6,
    ))
    base.add(ParagraphStyle(
        name="SectionTitle", parent=base["Heading1"], fontName=bold_font,
        fontSize=15, leading=18, textColor=colors.black, spaceAfter=7,
    ))
    base.add(ParagraphStyle(
        name="SubHead", parent=base["Heading2"], fontName=bold_font,
        fontSize=11, leading=14, textColor=colors.black, spaceBefore=5, spaceAfter=4,
    ))
    base.add(ParagraphStyle(
        name="BodyTight", parent=base["BodyText"], fontName=font,
        fontSize=10.5, leading=13, textColor=colors.black, spaceAfter=5,
    ))
    base.add(ParagraphStyle(
        name="Small", parent=base["BodyText"], fontName=font,
        fontSize=9.5, leading=12, textColor=colors.black, spaceAfter=3,
    ))
    base.add(ParagraphStyle(
        name="Equation", parent=base["BodyText"], fontName=font,
        fontSize=10.5, leading=15, alignment=TA_CENTER, spaceBefore=4, spaceAfter=8,
    ))
    base.add(ParagraphStyle(
        name="Caption", parent=base["BodyText"], fontName=italic_font,
        fontSize=9, leading=11, textColor=colors.black,
        alignment=TA_CENTER, spaceBefore=2, spaceAfter=5,
    ))
    base["Title"].fontName = bold_font
    base["Heading1"].fontName = bold_font
    base["Heading2"].fontName = bold_font
    base["BodyText"].fontName = font
    return base


def para(text: str, style):
    return Paragraph(text, style)


def chart(name: str, max_width: float = 7.2 * inch, max_height: float = 4.6 * inch):
    path = FIGURES / name
    if not path.exists():
        raise FileNotFoundError(f"Missing figure {path}; run pid_control.py first.")
    image = Image(str(path))
    image._restrictSize(max_width, max_height)
    return image


def load_metrics() -> dict[str, dict[str, float]]:
    if not METRICS_PATH.exists():
        raise FileNotFoundError(f"Missing {METRICS_PATH}; run pid_control.py first.")
    with METRICS_PATH.open(newline="", encoding="utf-8") as file:
        rows = list(csv.DictReader(file))
    return {
        row["controller"]: {key: float(value) for key, value in row.items() if key != "controller"}
        for row in rows
    }


def fmt(value: float, digits: int = 2) -> str:
    return "Not reached" if not math.isfinite(value) else f"{value:.{digits}f}"


def make_table(data, widths, font, bold_font, font_size=9.0):
    table = Table(data, colWidths=widths, repeatRows=1, hAlign="LEFT")
    table.setStyle(TableStyle([
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.black),
        ("FONTNAME", (0, 0), (-1, 0), bold_font),
        ("FONTNAME", (0, 1), (-1, -1), font),
        ("FONTSIZE", (0, 0), (-1, -1), font_size),
        ("LEADING", (0, 0), (-1, -1), font_size + 2),
        ("LINEBELOW", (0, 0), (-1, 0), 0.8, colors.black),
        ("LINEBELOW", (0, 1), (-1, -1), 0.3, colors.HexColor("#aaaaaa")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 4),
        ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ("TOPPADDING", (0, 0), (-1, -1), 3),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
    ]))
    return table


def footer(canvas, doc, font):
    canvas.saveState()
    canvas.setFont(font, 9)
    canvas.setFillColor(colors.black)
    canvas.drawRightString(7.82 * inch, 0.35 * inch, str(doc.page))
    canvas.restoreState()


def build():
    font, bold_font, italic_font, bold_italic_font = register_fonts()
    s = styles(font, bold_font, italic_font, bold_italic_font)
    metrics = load_metrics()
    doc = SimpleDocTemplate(
        str(OUTPUT), pagesize=letter, rightMargin=0.65 * inch,
        leftMargin=0.65 * inch, topMargin=0.55 * inch, bottomMargin=0.65 * inch,
        title="PID Control Assignment",
        author="",
    )
    story = []
    body = s["BodyTight"]
    small = s["Small"]

    story.extend([
        para("PID Control", s["CoverTitle"]),
        para("Physical AI Research Intern assignment", s["CoverSub"]),
        para("1. The basic idea", s["SectionTitle"]),
        para("A controller keeps reducing the gap between a desired value and the value a machine actually produces. It measures the result, calculates the error, and chooses a new input. The loop repeats many times per second.", body),
        para("<b>Everyday example: shower temperature.</b> The target is comfortable water. If the measured water is cold, you open the hot tap more; if it is too hot, you reduce it. A delay between adjustment and feeling the new temperature can cause overshoot, just as a robot can move past its target.", body),
        chart("feedback_loop.png", 7.1 * inch, 2.9 * inch),
        para("The controller does not need to know the perfect input in advance: feedback lets it correct from what the sensor reports. The quality of the sensor, actuator limits, delays, and controller update rate all affect the result.", body),
        PageBreak(),
    ])

    story.extend([
        para("2. The PID formula", s["SectionTitle"]),
        para("For a setpoint r(t), measured output x(t), error e(t), and controller output u(t):", body),
        para("e(t) = r(t) - x(t)<br/>u(t) = K<sub>p</sub> e(t) + K<sub>i</sub> integral[ e(tau) d tau ] + K<sub>d</sub> de(t)/dt", s["Equation"]),
        para("<b>For this position controller:</b> r and x are metres, e is metres, and u is force in newtons. Therefore Kp is N/m, Ki is N/(m s), and Kd is N s/m. The integral of error has units m s, while the error rate has units m/s.", body),
        para("<b>P - present error.</b> A proportional push grows with the current gap. It responds quickly, but with a spring load, a nonzero error is needed to maintain a nonzero force.", body),
        para("<b>I - past error.</b> The accumulated error increases the push while an offset persists. It can remove steady-state error, but may keep accumulating while a motor is saturated (integral windup).", body),
        para("<b>D - how error is changing.</b> Derivative action adds damping when motion is approaching the target quickly. It is sensitive to noisy measurements. The implementation uses derivative on measurement to avoid a setpoint kick.", body),
        para("<b>Small-step computer version.</b> With sample interval dt: e[k]=r[k]-x[k]; I[k]=I[k-1]+e[k]dt; D[k]=(e[k]-e[k-1])/dt; u[k]=Kp e[k]+Ki I[k]+Kd D[k]. In the code, D is instead -change(measurement)/dt, which is equivalent for a fixed target.", s["Equation"]),
        PageBreak(),
    ])

    story.extend([
        para("3. Test system: block, spring and damper", s["SectionTitle"]),
        para("The assignment specifies a 1 kg block attached to a spring and damper. Let x be position in metres and u be applied force in newtons. The damper resists velocity; the spring pulls toward zero.", body),
        para("m x'' + c x' + k x = u<br/>x'' = (u - c x' - k x)/m = u - 10 x' - 20 x", s["Equation"]),
        make_table([
            ["Quantity", "Value", "Meaning"],
            ["Mass m", "1 kg", "Inertia; force produces acceleration"],
            ["Damping c", "10 N s/m", "Opposes movement"],
            ["Spring k", "20 N/m", "Pulls the block toward x = 0"],
            ["Target", "1 m", "Desired block position"],
        ], [1.35 * inch, 1.15 * inch, 4.6 * inch], font, bold_font),
        Spacer(1, 8),
        para("<b>Why is a constant push needed?</b> At rest at x=1 m, velocity and acceleration are zero, so the spring force is kx = 20 N. The controller must keep supplying 20 N to balance that pull. P-only control supplies force only when error remains, which explains its steady offset.", body),
        para("<b>Numerical method.</b> The code updates its controller at a fixed dt and holds that force over the next interval. It advances position and velocity with a hand-coded fourth-order Runge-Kutta (RK4) integrator. This is more accurate than a large-step Euler update for the same sample interval.", body),
        PageBreak(),
    ])

    story.extend([
        para("4. How to judge a result", s["SectionTitle"]),
        para("A step response is the output after the target suddenly changes from 0 m to 1 m. Use defined measurements instead of saying only that one curve looks better.", body),
        chart("response_metrics.png", 7.15 * inch, 3.7 * inch),
        para("<b>Rise time:</b> time from first crossing 10% of the step to first crossing 90%. <b>Overshoot:</b> peak above target divided by step size, as a percent. <b>Settling time:</b> time after which the response stays inside a permanent +/-2% target band. <b>Steady-state error:</b> target minus the mean output over the final second. If a response never reaches a threshold or settles during the 8 s simulation, it is reported as not reached, not as zero.", body),
        para("These definitions make controller comparisons reproducible. Different applications may choose a different tolerance band or rise-time threshold, so state the definitions alongside the numbers.", body),
        PageBreak(),
    ])

    p_values = [(5, 0.2, 0.8), (20, 0.5, 0.5), (80, 0.8, 0.2), (200, 0.9091, 0.0909)]
    p_rows = [["Kp (N/m)", "x_ss (m)", "error (m)"]]
    p_rows.extend([[f"{kp:g}", f"{pos:.4f}", f"{err:.4f}"] for kp, pos, err in p_values])
    story.extend([
        para("5. Each part alone: P, then I, then D", s["SectionTitle"]),
        para("<b>P-only test.</b> The plot tries four proportional strengths. For a held target r=1 m, steady state has zero velocity and acceleration. Force balance gives u=kx. P control gives u=Kp(1-x), hence:", body),
        para("k x = Kp(1-x) &nbsp; -&gt; &nbsp; x<sub>ss</sub> = Kp/(Kp+k), &nbsp; e<sub>ss</sub> = k/(Kp+k)", s["Equation"]),
        make_table(p_rows, [2.0 * inch, 2.0 * inch, 2.0 * inch], font, bold_font),
        chart("p_only_sweep.png", 7.0 * inch, 2.8 * inch),
        para("As Kp grows, the remaining error shrinks but does not become zero for any finite Kp. The final positions in the plot match the calculation; higher P also makes the transient more aggressive.", small),
        PageBreak(),
    ])

    story.extend([
        para("5. Each part alone: adding I and D", s["SectionTitle"]),
        para("<b>Add I.</b> With Kp=80, adding Ki=40 accumulates the small residual error until the controller supplies the spring's required steady force. It removes the P-only offset, but can increase overshoot because accumulated error takes time to unwind.", body),
        chart("adding_integral.png", 6.9 * inch, 2.55 * inch),
        para("<b>Add D.</b> With Kp=80, adding Kd=25 reacts against rapid motion. It damps the transient, but does not cancel the spring-load offset; the PD response settles below the 1 m target.", body),
        chart("adding_derivative.png", 6.9 * inch, 2.55 * inch),
        para("In a real sensor, compute and filter D carefully: differentiating sample-to-sample noise can create large force fluctuations.", small),
        PageBreak(),
    ])

    metric_rows = [["Controller", "Rise (s)", "Overshoot (%)", "Settling (s)", "Final error (m)"]]
    for controller in ["P", "PI", "PD", "PID"]:
        m = metrics[controller]
        metric_rows.append([
            controller, fmt(m["rise_time_s"]), fmt(m["overshoot_percent"]),
            fmt(m["settling_time_s"]), f"{m['steady_state_error_m']:.4f}",
        ])
    story.extend([
        para("6. Putting P, I and D together", s["SectionTitle"]),
        para("For a fair comparison, each curve uses a declared gain set on the same plant and target. These are illustrative hand-selected values, not universal optimal gains.", body),
        chart("controller_comparison.png", 7.05 * inch, 3.35 * inch),
        make_table(metric_rows, [0.85 * inch, 1.05 * inch, 1.35 * inch, 1.1 * inch, 1.25 * inch], font, bold_font),
        Spacer(1, 5),
        para("<b>Gains (Kp, Ki, Kd):</b> P (200, 0, 0); PI (120, 60, 0); PD (100, 0, 30); PID (100, 40, 30), in the units given earlier. P and PD do not settle within 2% of the target because of the spring offset; PD also never reaches 90% of the 1 m step. In this example the selected PID reaches the band without overshoot, but its rise is slower. These trade-offs depend on the chosen gains.", small),
        PageBreak(),
    ])

    story.extend([
        para("7. Real-world problems and fixes", s["SectionTitle"]),
        chart("practical_problems.png", 7.05 * inch, 4.95 * inch),
        para("<b>(a) Saturation and windup.</b> The actuator is limited to +/-30 N, though the spring needs 20 N at the target. With Kp=120 and Ki=200, the no-anti-windup run overshoots by 25.8%; conditional integration avoids the demonstrated overshoot. It stops integrating when the output is saturated and the current error would push farther into saturation.", body),
        para("<b>(b) Noisy sensor.</b> Uniform measurement noise is bounded at +/-0.001 m (+/-1 mm). D amplifies the sample-to-sample changes; a first-order low-pass filter on D reduces the force chatter. Filtering trades noise reduction for some lag.", body),
        para("<b>(c) Derivative kick.</b> A target step creates a large derivative if D acts on error. Using -d(measured position)/dt leaves the target out of the derivative term while preserving damping from actual motion.", body),
        para("<b>(d) Slow updates.</b> With this gain set, changing the update interval from 0.01 s to 0.20 s makes the sampled loop unstable; the plotted slow-update response diverges. Sampling delay changes the loop dynamics, so choose an interval fast enough for the plant and retest the closed loop after every rate change.", body),
        PageBreak(),
    ])

    story.extend([
        para("8. Choosing gains and Ziegler-Nichols", s["SectionTitle"]),
        para("<b>Hand tuning, safely.</b> Start with I=D=0. Raise Kp gradually until response is fast but not dangerously oscillatory. Add D in small steps if overshoot or bouncing is a problem, while checking sensor noise and actuator effort. Add I slowly to remove remaining offset. After each change, compare the same rise, overshoot, settling, error and actuator-limit measures. Test expected loads and limits; reduce gains if oscillations grow.", body),
        para("<b>Second plant.</b> For G(s)=1/(s+1)^3 with unity negative feedback and P-only gain K, the closed-loop characteristic polynomial is (s+1)^3+K. At the stability boundary, K<sub>u</sub>=8; the oscillation frequency is sqrt(3) rad/s and P<sub>u</sub>=2 pi/sqrt(3)=3.628 s. This theoretical result is checked against the simulated sustained oscillation.", body),
        chart("ziegler_nichols.png", 7.0 * inch, 3.15 * inch),
        make_table([
            ["Rule", "Kp", "Ti (s)", "Td (s)", "Equivalent Ki / Kd"],
            ["P", "0.5 Ku = 4.0", "-", "-", "Ki=0, Kd=0"],
            ["PI", "0.45 Ku = 3.6", "Pu/1.2 = 3.023", "-", "Ki=1.191, Kd=0"],
            ["PID", "0.6 Ku = 4.8", "Pu/2 = 1.814", "Pu/8 = 0.453", "Ki=2.646, Kd=2.177"],
        ], [0.75 * inch, 1.15 * inch, 1.25 * inch, 1.15 * inch, 2.25 * inch], font, bold_font, font_size=8.2),
        para("The classical ZN PID setting is intentionally a starting point: on this simulation it overshoots by 52.7% and settles in about 9.91 s. A refined (Kp,Ki,Kd)=(2.0,0.5,1.5) gives 0% overshoot and settles in about 4.22 s, with a slower 2.32 s rise. The safer, less oscillatory trade-off is preferable here.", small),
        para("In the table, Ti is the integral time and Td is the derivative time, both in seconds. To convert the ideal ZN form to the parallel form used by the code, use Ki=Kp/Ti and Kd=Kp*Td.", small),
        PageBreak(),
    ])

    story.extend([
        para("9. Reusable code and how to reproduce it", s["SectionTitle"]),
        para("The PID class in pid_control.py is reusable: it accepts Kp/Ki/Kd, an optional output limit, derivative-filter time constant, derivative-on-measurement selection, and anti-windup selection. It has no ready-made controller dependency.", body),
        para("<b>Update sequence:</b> validate dt; calculate error; estimate and optionally filter derivative; form a candidate integral; if saturation and the error would deepen it, reject that integration step; sum P/I/D; clamp the command to actuator limits; store current values for the next update.", body),
        para("<b>Plant state:</b> [position, velocity]. The simulated acceleration is (force - 10 velocity - 20 position)/1. RK4 advances that state using the held controller output. Seeded noise makes sensor-noise plots repeatable.", body),
        para("<b>Recreate all graphs and measurements</b><br/>python -m pip install -r requirements.txt<br/>python pid_control.py<br/>python build_report.py", s["Equation"]),
        para("The first command installs NumPy, Matplotlib, and ReportLab; ReportLab is only needed for PDF generation. The second regenerates every image in figures/ and metrics.csv. The third assembles those outputs into this PDF. See README.md for output descriptions, assumptions and GitHub publishing steps.", body),
        para("<b>Limitations.</b> This idealized linear model omits friction nonlinearities, actuator delay, backlash, quantization and changing loads. Real robots require safe limits, hardware-aware tuning, and validation on the actual mechanism.", body),
        PageBreak(),
    ])

    story.extend([
        para("10. Real robots and PID myths", s["SectionTitle"]),
        make_table([
            ["Example", "What PID controls"],
            ["DC motor", "Speed loop adjusts voltage/current to reach a requested shaft speed."],
            ["Drone", "Nested rate/attitude loops correct angular motion; gains and sensing must be tuned for the airframe."],
            ["Robot arm", "Joint position or velocity control tracks a trajectory while countering load disturbances."],
            ["Line-following robot", "Image/sensor position error steers the wheels to keep the line centered."],
            ["Vehicle cruise control", "Throttle or motor torque corrects the difference between requested and measured speed."],
        ], [1.55 * inch, 5.2 * inch], font, bold_font),
        Spacer(1, 7),
        para("<b>Common myths, corrected</b>", s["SubHead"]),
        para("<b>Myth:</b> PID always makes a system stable. <b>Correction:</b> unsuitable gains, delay, saturation or sampling can cause oscillation or instability.", body),
        para("<b>Myth:</b> one gain set works on every robot. <b>Correction:</b> dynamics, units, payload, actuator and sample period matter.", body),
        para("<b>Myth:</b> integral action is always beneficial. <b>Correction:</b> it removes persistent error but can wind up at limits and worsen overshoot.", body),
        para("<b>Myth:</b> derivative predicts the future and is always calming. <b>Correction:</b> it responds to measured rate; noise and abrupt setpoint changes can create large commands.", body),
        para("<b>Myth:</b> zero steady-state error means a good controller. <b>Correction:</b> rise time, overshoot, settling, error, noise and actuator effort all matter.", body),
        para("<b>AI-use disclosure.</b> AI assistance was used to organize explanations, draft documentation, and help check the derivations and simulation approach. The included code generates the reported results; rerun it and verify any gain changes before relying on them.", small),
    ])

    page_footer = lambda canvas, document: footer(canvas, document, font)
    doc.build(story, onFirstPage=page_footer, onLaterPages=page_footer)
    print(f"Created {OUTPUT}")


if __name__ == "__main__":
    build()
